<?php use App\Core\Authorization; ?>
<header class="admin-page-head"><div><span class="eyebrow">Users & Access</span><h1>کاربران و نقش‌ها</h1><p>نقش سیستمی و وضعیت دسترسی هر حساب را مدیریت کنید.</p></div><span class="admin-count"><?= number_format(count($users)) ?> نتیجه</span></header>
<?php if (isset($_GET['updated'])): ?><div class="alert alert--success" role="status">دسترسی کاربر با موفقیت به‌روزرسانی شد.</div><?php endif; ?>
<?php if (($_GET['error'] ?? '') === 'self-access'): ?><div class="alert alert--danger" role="alert">برای جلوگیری از قفل‌شدن پنل، نمی‌توانید نقش یا وضعیت حساب فعلی خود را تغییر دهید.</div><?php endif; ?>
<form class="admin-filters" method="get" action="/admin/users"><label><span class="sr-only">جستجو</span><input class="form-control" type="search" name="q" value="<?= e($filters['query']) ?>" placeholder="نام یا ایمیل..."></label><label><span class="sr-only">نقش</span><select class="form-select" name="role"><option value="all">همه نقش‌ها</option><?php foreach ($roles as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filters['role']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label><span class="sr-only">وضعیت</span><select class="form-select" name="status"><option value="all">همه وضعیت‌ها</option><option value="active" <?= $filters['status']==='active'?'selected':'' ?>>فعال</option><option value="suspended" <?= $filters['status']==='suspended'?'selected':'' ?>>تعلیق‌شده</option></select></label><button class="btn btn--secondary" type="submit">اعمال فیلتر</button></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>کاربر</th><th>عضویت</th><th>آخرین ورود</th><th>دسترسی</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><div class="table-user"><span><?= e(mb_substr($user['name'],0,1)) ?></span><div><strong><?= e($user['name']) ?></strong><small class="ltr"><?= e($user['email']) ?></small></div></div></td><td class="ltr"><?= e(substr((string)$user['created_at'],0,10)) ?></td><td class="ltr"><?= e($user['last_login_at'] ? substr((string)$user['last_login_at'],0,16) : '—') ?></td><td><form class="access-form" method="post" action="/admin/users/<?= e($user['id']) ?>/access"><?= csrf_field() ?><select class="form-select" name="account_role" aria-label="نقش <?= e($user['name']) ?>"><?php foreach ($roles as $key=>$label): ?><option value="<?= e($key) ?>" <?= Authorization::role($user)===$key?'selected':'' ?> <?= $key==='super_admin' && Authorization::role($admin)!=='super_admin'?'disabled':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><select class="form-select" name="status" aria-label="وضعیت <?= e($user['name']) ?>"><option value="active" <?= ($user['status']??'active')==='active'?'selected':'' ?>>فعال</option><option value="suspended" <?= ($user['status']??'active')==='suspended'?'selected':'' ?>>تعلیق</option></select><button class="btn btn--primary btn--sm" type="submit" <?= $user['id']===($admin['id']??'')?'disabled':'' ?>>ذخیره</button></form></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="4"><div class="content-empty"><span class="content-empty__icon">⌕</span><div><h3>کاربری پیدا نشد</h3><p>فیلترها یا عبارت جستجو را تغییر دهید.</p></div></div></td></tr><?php endif; ?></tbody></table></div>
